pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

/**
 * @title IFightToken
 * @dev Interface for the game's ERC20 currency.
 */
interface IFightToken {
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
}

/**
 * @title FightToken
 * @dev A simple ERC20 token to be used as the in-game currency for the FightGame.
 * The owner of the contract can mint new tokens. This contract is deployable
 * and its address should be used to initialize the FightGame contract.
 */
contract FightToken is ERC20, Ownable {
    /**
     * @dev Sets the name and symbol for the token.
     */
    constructor() ERC20("Fight Token", "FIGHT") {}

    /**
     * @dev Creates `amount` tokens and assigns them to `account`, increasing
     * the total supply. Can only be called by the contract owner.
     *
     * Emits a {Transfer} event with `from` set to the zero address.
     *
     * Requirements:
     * - `to` cannot be the zero address.
     */
    function mint(address to, uint256 amount) public onlyOwner {
        _mint(to, amount);
    }
}


/**
 * @title FightGame
 * @dev An on-chain fighting game where players mint NFT fighters and battle each other.
 * This contract manages the fighters (as ERC721 tokens), their stats, and the fight logic.
 * It is a concrete, deployable contract.
 */
contract FightGame is ERC721, Ownable, Pausable, ReentrancyGuard {
    using Counters for Counters.Counter;

    // Counter for minting unique token IDs.
    Counters.Counter private _tokenIdCounter;

    // --- Structs and Mappings ---

    struct Fighter {
        uint128 hp;
        uint64 attack;
        uint64 defense;
        uint64 wins;
        uint64 losses;
    }

    mapping(uint256 => Fighter) public fighters;

    // --- State Variables ---

    IFightToken public fightToken;
    uint256 public mintPrice;

    uint256 public constant MAX_STAT_POINTS = 100;
    uint256 public constant MIN_STAT_POINTS = 10;

    // --- Events ---

    event FighterCreated(address indexed owner, uint256 indexed tokenId, uint256 hp, uint256 attack, uint256 defense);
    event FightOutcome(uint256 indexed winnerId, uint256 indexed loserId, uint256 rounds);

    // --- Constructor ---

    /**
     * @dev Sets the NFT collection name and symbol. The constructor is empty
     * of arguments per requirements. Use the `initialize` function for setup.
     */
    constructor() ERC721("FightGame Fighter", "FGF") {
        // Start token IDs from 1 for safety, as ID 0 can be ambiguous.
        _tokenIdCounter.increment();
    }

    // --- Initializer ---

    /**
     * @dev Initializes contract parameters. Can only be called once by the owner.
     * This pattern is used to allow for parameter setting after deployment without
     * a constructor that takes arguments.
     * @param _fightTokenAddress The address of the ERC20 currency for the game.
     * @param _initialMintPrice The initial price to mint a new fighter.
     */
    function initialize(address _fightTokenAddress, uint256 _initialMintPrice) public onlyOwner {
        require(address(fightToken) == address(0), "FightGame: Already initialized");
        require(_fightTokenAddress != address(0), "FightGame: Zero address for token");

        fightToken = IFightToken(_fightTokenAddress);
        mintPrice = _initialMintPrice;
    }

    // --- Core Game Logic ---

    /**
     * @notice Mints a new fighter NFT for the caller.
     * @dev The caller must first approve this contract to spend `mintPrice` of FightToken.
     * Fighter stats are generated pseudo-randomly based on on-chain data.
     */
    function createFighter() external whenNotPaused nonReentrant {
        require(address(fightToken) != address(0), "FightGame: Not initialized");
        require(mintPrice > 0, "FightGame: Minting price must be greater than zero");

        uint256 price = mintPrice;
        require(fightToken.balanceOf(_msgSender()) >= price, "FightGame: Insufficient FIGHT balance");
        require(fightToken.allowance(_msgSender(), address(this)) >= price, "FightGame: Token allowance not set");

        fightToken.transferFrom(_msgSender(), address(this), price);

        uint256 tokenId = _tokenIdCounter.current();
        _tokenIdCounter.increment();

        (uint256 hp, uint256 attack, uint256 defense) = _generateStats(tokenId);

        fighters[tokenId] = Fighter({
            hp: uint128(hp),
            attack: uint64(attack),
            defense: uint64(defense),
            wins: 0,
            losses: 0
        });

        _safeMint(_msgSender(), tokenId);
        emit FighterCreated(_msgSender(), tokenId, hp, attack, defense);
    }

    /**
     * @notice Initiates a fight between two fighters.
     * @param attackerId The token ID of the fighter initiating the attack.
     * @param defenderId The token ID of the fighter being challenged.
     */
    function fight(uint256 attackerId, uint256 defenderId) external whenNotPaused nonReentrant {
        require(ownerOf(attackerId) == _msgSender(), "FightGame: You do not own the attacker");
        require(_exists(defenderId), "FightGame: Defender does not exist");
        require(attackerId != defenderId, "FightGame: Cannot fight yourself");

        Fighter storage attacker = fighters[attackerId];
        Fighter storage defender = fighters[defenderId];

        // A simple, deterministic fight resolution to save gas.
        // Calculate how many hits each fighter needs to land to win.
        uint256 attackerDamage = attacker.attack > defender.defense ? attacker.attack - defender.defense : 1;
        uint256 defenderDamage = defender.attack > attacker.attack ? defender.attack - attacker.attack : 1;

        uint256 attackerRoundsToWin = (defender.hp + attackerDamage - 1) / attackerDamage;
        uint256 defenderRoundsToWin = (attacker.hp + defenderDamage - 1) / defenderDamage;

        uint256 winnerId;
        uint256 loserId;
        uint256 rounds;

        // Use a pseudo-random seed to determine who strikes first. In a tie of rounds, the first striker wins.
        bool attackerStrikesFirst = _getTurn(attackerId, defenderId);

        if (attackerStrikesFirst ? (attackerRoundsToWin <= defenderRoundsToWin) : (attackerRoundsToWin < defenderRoundsToWin)) {
            winnerId = attackerId;
            loserId = defenderId;
            rounds = attackerRoundsToWin;
        } else {
            winnerId = defenderId;
            loserId = attackerId;
            rounds = defenderRoundsToWin;
        }

        fighters[winnerId].wins++;
        fighters[loserId].losses++;

        emit FightOutcome(winnerId, loserId, rounds);
    }

    // --- View Functions ---

    /**
     * @dev Returns the total number of fighters minted so far.
     */
    function totalSupply() public view returns (uint256) {
        // Counter starts at 1, so current() - 1 is the total minted supply.
        return _tokenIdCounter.current() - 1;
    }

    /**
     * @dev Base URI for computing {tokenURI}.
     */
    function _baseURI() internal pure override returns (string memory) {
        return "https://api.fightgame.example/fighters/";
    }

    // --- Admin Functions ---

    /**
     * @dev Pauses the game. Minting, fighting, and transfers will be disabled.
     */
    function pause() public onlyOwner {
        _pause();
    }

    /**
     * @dev Unpauses the game.
     */
    function unpause() public onlyOwner {
        _unpause();
    }

    /**
     * @dev Updates the price for minting a new fighter.
     * @param _newPrice The new price in the smallest unit of FightToken.
     */
    function setMintPrice(uint256 _newPrice) public onlyOwner {
        mintPrice = _newPrice;
    }

    /**
     * @dev Withdraws the accumulated FightToken balance from this contract to the owner.
     */
    function withdrawTokens() public onlyOwner {
        uint256 balance = fightToken.balanceOf(address(this));
        require(balance > 0, "FightGame: No tokens to withdraw");
        fightToken.transfer(owner(), balance);
    }

    // --- Internal and Hook Functions ---

    /**
     * @dev See {ERC721-_beforeTokenTransfer}.
     * This hook is used to prevent token transfers when the contract is paused,
     * adding an extra layer of control during emergencies.
     */
    function _beforeTokenTransfer(address from, address to, uint256 firstTokenId, uint256 batchSize)
        internal
        whenNotPaused
        override
    {
        super._beforeTokenTransfer(from, to, firstTokenId, batchSize);
    }

    /**
     * @dev Generates pseudo-random stats for a new fighter.
     * WARNING: This is NOT a secure source of randomness and can be manipulated by miners.
     * It is used here for simplicity in a game context. For high-value assets,
     * a secure oracle like Chainlink VRF should be used.
     * @param tokenId The ID of the token being created.
     */
    function _generateStats(uint256 tokenId) private view returns (uint256 hp, uint256 attack, uint256 defense) {
        uint256 randomSeed = uint256(keccak256(abi.encodePacked(block.timestamp, _msgSender(), tokenId)));

        hp = (randomSeed % (MAX_STAT_POINTS - MIN_STAT_POINTS + 1)) + MIN_STAT_POINTS;
        randomSeed = uint256(keccak256(abi.encodePacked(randomSeed)));
        attack = (randomSeed % (MAX_STAT_POINTS - MIN_STAT_POINTS + 1)) + MIN_STAT_POINTS;
        randomSeed = uint256(keccak256(abi.encodePacked(randomSeed)));
        defense = (randomSeed % (MAX_STAT_POINTS - MIN_STAT_POINTS + 1)) + MIN_STAT_POINTS;
    }

    /**
     * @dev Determines who attacks first in a fight based on a pseudo-random hash.
     * WARNING: This is NOT a secure source of randomness and is susceptible to block manipulation.
     */
    function _getTurn(uint256 attackerId, uint256 defenderId) private view returns (bool) {
        uint256 seed = uint256(keccak256(abi.encodePacked(blockhash(block.number - 1), attackerId, defenderId)));
        return seed % 2 == 0;
    }
}

